
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_pbe_sol_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_pbe_sol", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-7.322811301005842e-02, -7.220826671298282e-02, -7.074400988529633e-02, -6.864323040785456e-02, -6.563257977342195e-02, -6.132665992173594e-02, -5.519709968751232e-02, -4.659102319692686e-02, -3.506202964707424e-02, -2.212216249929532e-02, -1.655744373019223e-02, -4.297540911846033e-02, -4.884010972351373e-02, -3.652776470798546e-02, -2.073145579432967e-02, -6.013912917740473e-03, -3.994806543722092e-04, -3.848848162712823e-06, -3.978833840642441e-09, -1.575312743695181e-13]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


